 "decisions": [
  {
   "title": "Data moves to the target database",
   "context": "The legacy keeps ORDENES and CUENTAS in VSAM KSDS files accessed with CICS READ/REWRITE.",
   "decision": "data_strategy is migration: ORDENES becomes payment_orders and CUENTAS becomes accounts, with the legacy precision (9(7), 9(5), S9(9)V99, S9(11)V99, S9(3)V99).",
   "consequences": "The service reads and writes relational tables. The golden master traces load the legacy table contents into these tables."
  },
  {
   "title": "PAGODEB is folded into the PayOrder use case",
   "context": "PAGOORD calls PAGODEB with LINK to debit the account, and both work on the same unit of work. The source of PAGODEB is available and its data moves.",
   "decision": "The rules of PAGODEB (RULE-001 to RULE-005) are implemented inside PayOrder through AccountRepository, in the same order as the legacy (not found, type mismatch, inactive, balance below amount, debit). DEB-RESP '30' and '40' end as INVALID_ACCOUNT, '10' as ACCOUNT_INACTIVE and '20' as INSUFFICIENT_FUNDS, as PAGOORD does.",
   "consequences": "There is no DebitGateway port. A balance equal to the amount is allowed, as in the legacy."
  },
  {
   "title": "One transaction replaces the CICS syncpoint",
   "context": "PAGOORD rewrites the account (PAGODEB) and the order, and commits with SYNCPOINT at line 172. There is no rollback point in the legacy: every rejection happens before the first write.",
   "decision": "PayOrder runs in one transaction that begins at line 37 and commits at line 172. No savepoints and no rollbacks are declared.",
   "consequences": "If a technical failure happens after the debit (e.g. the movement registration fails) the whole transaction is undone, which the CICS task would do on abend."
  },
  {
   "title": "Rejections are business errors",
   "context": "The traces show that every rejection returns status -1 with only the message (MENSAJE) and leaves the tables unchanged.",
   "decision": "Each rejection is a business error with a stable code and the legacy message. legacy_code is -1 for all of them and legacy_message is MENSAJE.",
   "consequences": "The HTTP layer maps each error code to a 4xx response with the message. The screen message 'TECLA NO VALIDA' and the map handling are not translated."
  },
  {
   "title": "Amount is received as a decimal",
   "context": "The screen field VALORI is a digit string converted with NUMVAL/100 (implied decimals). The traces provide VALOR as a decimal amount ('1500.00') that is compared with ORD_VALOR.",
   "decision": "The service receives amount as decimal(11,2,signed) and compares it with the order value exactly (scale 2). The conversion of the screen digits is a concern of the client.",
   "consequences": "RULE-012 is kept as an equality check between the typed amount and the order value."
  },
  {
   "title": "Commission rule kept as constants of the domain",
   "context": "RULE-013: 50,000 or more pays 0, WEB pays 1.00 and any other channel pays 2.50; the total debited is value plus commission.",
   "decision": "The calculation is done in the use case with decimal arithmetic at scale 2; it is not stored in a table.",
   "consequences": "A change of tariff requires a code change."
  },
  {
   "title": "Pseudo-conversational state and screens are not translated",
   "context": "PAGOORD and PAGOMNU use maps, EIBAID, a 13-byte commarea (CA-ULTIMA-ORDEN) and XCTL/RETURN TRANSID.",
   "decision": "The services are stateless HTTP endpoints. The menu use case only returns the destination (PAGOORD, END) and the message; the commarea and the PF3/ENTER handling belong to the client.",
   "consequences": "CA-ULTIMA-ORDEN is not stored in the target. Option 9 returns destination END with the message 'SESION TERMINADA'."
  },
  {
   "title": "PAGOMOV is an external program behind a port",
   "context": "PAGOMOV is not in the inputs and is stubbed in the traces; PAGOORD does not check its return status and uses only MOV_NUMERO.",
   "decision": "MovementGateway.registerMovement calls PAGOMOV with MOV_ORDEN and returns MOV_NUMERO. Its return status is not mapped.",
   "consequences": "The traces replay PAGOMOV with its recorded stub."
  }
 ],
