package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.SelectMenuOptionRequest;
import com.bank.payments.adapters.in.rest.SelectMenuOptionResponse;
import com.bank.payments.domain.error.BusinessError;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * Tests of SelectMenuOption (legacy PAGOMNU, paragraph 2000-ELEGIR-OPCION, lines 43-55).
 * Pins RULE-006.
 */
class SelectMenuOptionServiceTest {

    private final SelectMenuOptionService service = new SelectMenuOptionService();

    private void assertInvalidOption(String option) {
        assertThatThrownBy(() -> service.execute(new SelectMenuOptionRequest(option)))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> {
                    BusinessError be = (BusinessError) e;
                    assertThat(be.code()).isEqualTo("INVALID_OPTION");
                    assertThat(be.legacyCode()).isEqualTo("OPCION_NO_VALIDA");
                    assertThat(be.getMessage()).isEqualTo("OPCION NO VALIDA");
                });
    }

    // RULE-006: WHEN '1' -> XCTL PROGRAM('PAGOORD')
    @Test
    void user_selects_payment_order_entry() {
        SelectMenuOptionResponse response = service.execute(new SelectMenuOptionRequest("1"));

        assertThat(response.destination()).isEqualTo("PAGOORD");
    }

    // RULE-006: WHEN '9' -> PERFORM 9000-TERMINAR (WS-FIN = 'SESION TERMINADA'), destination END
    @Test
    void user_exits() {
        SelectMenuOptionResponse response = service.execute(new SelectMenuOptionRequest("9"));

        assertThat(response.destination()).isEqualTo("END");
        assertThat(response.message()).isEqualTo("SESION TERMINADA");
    }

    // RULE-006: WHEN OTHER -> 'OPCION NO VALIDA'
    @Test
    void invalid_option() {
        assertInvalidOption("5");
    }

    // RULE-006: WHEN OTHER with the digit just below the valid ones
    @Test
    void invalid_option_zero() {
        assertInvalidOption("0");
    }

    // RULE-006: WHEN OTHER with the digit just after '9' range neighbours
    @Test
    void invalid_option_eight() {
        assertInvalidOption("8");
    }

    // RULE-006: WHEN OTHER with option 2 (next to '1')
    @Test
    void invalid_option_two() {
        assertInvalidOption("2");
    }

    // RULE-006: WHEN OTHER with a letter
    @Test
    void invalid_option_letter() {
        assertInvalidOption("A");
    }

    // RULE-006: WHEN OTHER with a blank field (field not filled on the map)
    @Test
    void invalid_option_blank() {
        assertInvalidOption(" ");
    }

    // RULE-006: WHEN OTHER with an empty value
    @Test
    void invalid_option_empty() {
        assertInvalidOption("");
    }

    // RULE-006: WHEN OTHER, the only remaining branch for an absent value
    @Test
    void invalid_option_null() {
        assertInvalidOption(null);
    }

    // RULE-006: the comparison is an exact match on the character, not a numeric one
    @Test
    void invalid_option_other_special_character() {
        assertInvalidOption("-");
    }

    // RULE-006: a rejected option does not behave as option 1 or 9 (repeat gives same rejection)
    @Test
    void invalid_option_repeated_gives_same_rejection() {
        assertInvalidOption("5");
        assertInvalidOption("5");
    }

    // RULE-006: valid options remain valid after a rejection (stateless)
    @Test
    void valid_option_after_invalid_option() {
        assertInvalidOption("7");

        assertThat(service.execute(new SelectMenuOptionRequest("1")).destination()).isEqualTo("PAGOORD");
        assertThat(service.execute(new SelectMenuOptionRequest("9")).destination()).isEqualTo("END");
    }
}


